def strategy(
    agent_id: int,
    my_history: list[dict],
    observations: list[dict],
    round_num: int,
    recipient_id: int,
    population_size: int
) -> bool:
    # Tit-for-two-tats: defect only if the last two interactions with this
    # recipient (as the donor to us) were both defections.
    last_two = []
    for entry in reversed(my_history):
        if entry["role"] == "recipient" and entry["partner"] == recipient_id:
            last_two.append(entry["partner_action"])
            if len(last_two) == 2:
                break
    if len(last_two) == 2 and all(action == "not_donate" for action in last_two):
        return False
    # In all other cases (less than two encounters, or at least one donation)
    return True

def strategy(
    agent_id: int,
    my_history: list[dict],
    observations: list[dict],
    round_num: int,
    recipient_id: int,
    population_size: int
) -> bool:
    # Collect all past partner actions when interacting with this recipient
    partner_actions = []
    for entry in my_history:
        if entry["partner"] == recipient_id:
            partner_actions.append(entry["partner_action"])

    if not partner_actions:
        # No history: cooperate on first encounter
        return True

    # If the last interaction was a defection, defect immediately
    if partner_actions[-1] == "not_donate":
        return False

    # Otherwise, cooperate if at least 40% of past interactions were donations
    donate_count = sum(1 for act in partner_actions if act == "donate")
    return donate_count >= 0.4 * len(partner_actions)

def strategy(
    agent_id: int,
    my_history: list[dict],
    observations: list[dict],
    round_num: int,
    recipient_id: int,
    population_size: int
) -> bool:
    # Collect all past actions from this recipient
    partner_actions = []
    for entry in my_history:
        if entry["partner"] == recipient_id:
            partner_actions.append(entry["partner_action"])

    # No history: cooperate on first encounter
    if not partner_actions:
        return True

    # Majority rule: cooperate if donated at least as often as not donated
    donations = sum(1 for a in partner_actions if a == 'donate')
    return donations >= (len(partner_actions) - donations)

def strategy(
    agent_id: int,
    my_history: list[dict],
    observations: list[dict],
    round_num: int,
    recipient_id: int,
    population_size: int
) -> bool:
    # Tit-for-tat: cooperate if last interaction with this recipient was donate
    for entry in reversed(my_history):
        if entry["role"] == "donor" and entry["partner"] == recipient_id:
            return entry["partner_action"] == "donate"
        if entry["role"] == "recipient" and entry["partner"] == recipient_id:
            return entry["partner_action"] == "donate"
    # No history with this recipient: cooperate
    return True

def strategy(
